const app = document.getElementById('app');
const toast = document.getElementById('toast');

const LS = {
  get(key, fallback=null){ try { const v = localStorage.getItem(key); return v === null ? fallback : JSON.parse(v); } catch { return fallback; } },
  set(key, value){ localStorage.setItem(key, JSON.stringify(value)); },
  del(key){ localStorage.removeItem(key); }
};

const state = {
  route: location.hash.replace('#/','') || 'landing',
  user: LS.get('mjs_user', null), token: localStorage.getItem('mjs_token') || '',
  dark: localStorage.getItem('mjs_theme') !== 'light', lang: localStorage.getItem('mjs_lang') || 'EN', menu:false,
  sourceImage: localStorage.getItem('mjs_source') || '', processedImage: localStorage.getItem('mjs_processed') || '', vectorSVG: localStorage.getItem('mjs_vector') || '',
  jerseyColor: localStorage.getItem('mjs_color') || '#111c1a', accentColor: localStorage.getItem('mjs_accent') || '#9cff45',
  playerName: localStorage.getItem('mjs_name') || 'YOUR NAME', playerNumber: localStorage.getItem('mjs_number') || '10',
  logoData: localStorage.getItem('mjs_logo') || '', pattern: localStorage.getItem('mjs_pattern') || 'slashes',
  cleanupThreshold: +(localStorage.getItem('mjs_threshold') || 54), colorStep: +(localStorage.getItem('mjs_colorstep') || 32),
  projects: LS.get('mjs_projects', []), orders: LS.get('mjs_orders', []), team: LS.get('mjs_team', []), assets: LS.get('mjs_assets', []), bulkRows: LS.get('mjs_bulk', []),
  convertSource: '', convertName: '',
};

function esc(s){ return String(s ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function notify(msg){ toast.textContent=msg; toast.classList.add('show'); clearTimeout(notify.t); notify.t=setTimeout(()=>toast.classList.remove('show'),2400); }
function goto(route){ location.hash = '#/'+route; }
window.goto = goto;
window.addEventListener('hashchange',()=>{ state.route=location.hash.replace('#/','')||'landing'; state.menu=false; render(); });
function saveDesignState(){
  localStorage.setItem('mjs_color',state.jerseyColor); localStorage.setItem('mjs_accent',state.accentColor); localStorage.setItem('mjs_name',state.playerName); localStorage.setItem('mjs_number',state.playerNumber); localStorage.setItem('mjs_logo',state.logoData); localStorage.setItem('mjs_pattern',state.pattern);
}
function designSnapshot(){ return {color:state.jerseyColor,accent:state.accentColor,name:state.playerName,number:state.playerNumber,logo:state.logoData,pattern:state.pattern}; }
function applySnapshot(x={}){ state.jerseyColor=x.color||state.jerseyColor; state.accentColor=x.accent||state.accentColor; state.playerName=x.name||state.playerName; state.playerNumber=x.number||state.playerNumber; state.logoData=x.logo ?? state.logoData; state.pattern=x.pattern||state.pattern; saveDesignState(); }

function patternMarkup(pattern, accent){
  if(pattern==='none') return '';
  if(pattern==='chevrons') return `<path d="M86 135l64 42 64-42M86 178l64 42 64-42M86 221l64 42 64-42" fill="none" stroke="${accent}" stroke-width="9" opacity=".17"/>`;
  if(pattern==='waves') return `<path d="M88 145 Q118 125 148 145 T208 145 M88 190 Q118 170 148 190 T208 190 M88 235 Q118 215 148 235 T208 235" fill="none" stroke="${accent}" stroke-width="8" opacity=".16"/>`;
  return `<path d="M94 138 L127 100 L143 326 L116 326Z M206 138 L173 100 L157 326 L184 326Z" fill="${accent}" opacity=".14"/>`;
}
function jerseySVG({id='hero',front=true,color=state.jerseyColor,accent=state.accentColor,name=state.playerName,number=state.playerNumber,logo=state.logoData,pattern=state.pattern,compact=false}={}){
  const grad=`grad-${id}`;
  const safeName=esc(name), safeNumber=esc(number);
  const logoMarkup = logo ? `<image href="${logo}" x="114" y="96" width="72" height="72" preserveAspectRatio="xMidYMid meet"/>` : `<g transform="translate(150 132)"><path d="M-30,-16 L0,-32 30,-16 22,18 0,35 -22,18Z" fill="${accent}" opacity=".92"/><text x="0" y="8" fill="#06130d" font-size="26" font-weight="900" text-anchor="middle">MJ</text></g>`;
  return `<svg class="jersey-svg ${compact?'compact':''}" viewBox="0 0 300 360" xmlns="http://www.w3.org/2000/svg">
  <defs><linearGradient id="${grad}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${color}"/><stop offset="1" stop-color="#050b0a"/></linearGradient></defs>
  <path d="M77 66 L107 35 Q150 18 193 35 L223 66 L278 90 252 145 218 130 211 326 89 326 82 130 48 145 22 90Z" fill="url(#${grad})" stroke="${accent}" stroke-width="3"/>
  <path d="M107 35 Q150 76 193 35 L178 25 Q150 55 122 25Z" fill="#020806" stroke="${accent}" stroke-width="3"/>
  <path d="M78 68 L111 88 96 113 64 94Z M222 68 L189 88 204 113 236 94Z" fill="${accent}" opacity=".85"/>
  ${patternMarkup(pattern,accent)}
  ${front ? `${logoMarkup}<text x="150" y="214" fill="#fff" font-size="22" font-weight="900" text-anchor="middle" letter-spacing="1">TEAM</text><text x="150" y="275" fill="${accent}" stroke="#fff" stroke-width="1" font-size="68" font-weight="900" text-anchor="middle">${safeNumber}</text>` : `<text x="150" y="145" fill="#fff" font-size="22" font-weight="800" text-anchor="middle">${safeName}</text><text x="150" y="245" fill="none" stroke="#fff" stroke-width="3" font-size="96" font-weight="900" text-anchor="middle">${safeNumber}</text>`}
  </svg>`;
}

function brand(){ return `<div class="brand" onclick="goto('${state.user?'dashboard':'landing'}')"><span class="brandmark"></span><div class="brandtext">My Jersey<small>Studio</small></div></div>`; }
function topbar(active='Home'){
  const links=[['Home','dashboard'],['Design','customize'],['Production','production'],['My Projects','projects'],['Templates','templates']];
  return `<header class="topbar">${brand()}<nav class="nav">${links.map(([n,r])=>`<a href="#/${state.user?r:(n==='Home'?'landing':'login')}" class="${n===active?'active':''}">${n}</a>`).join('')}</nav><div class="top-actions"><button class="iconbtn" title="Theme" onclick="toggleTheme()">◐</button><button class="iconbtn" title="Language" onclick="toggleLang()">${state.lang==='EN'?'◎':'বাং'}</button><button class="btn" onclick="goto('${state.user?'dashboard':'login'}')">${state.user?'Workspace':'Sign In'}</button><button class="btn primary" onclick="goto('${state.user?'vector':'register'}')">${state.user?'New Design':'Get Started'} →</button><button class="iconbtn" onclick="toggleMenu()">☰</button></div></header>`;
}
window.toggleTheme=()=>{state.dark=!state.dark;localStorage.setItem('mjs_theme',state.dark?'dark':'light');applyTheme();notify(state.dark?'Dark mode':'Light mode preview');};
function applyTheme(){document.body.classList.toggle('light-preview',!state.dark);}
window.toggleLang=()=>{state.lang=state.lang==='EN'?'বাংলা':'EN';localStorage.setItem('mjs_lang',state.lang);render();notify(`Language: ${state.lang}`);};
window.toggleMenu=()=>{state.menu=!state.menu;document.querySelector('.drawer-backdrop')?.classList.toggle('open',state.menu);};

const menuItems=[
  ['Dashboard','dashboard','⌂','Overview, stats and recent activity'],['Image To Vector','vector','◈','Convert images to clean vector'],['Customize Design','customize','✦','Create and edit jersey designs'],['Preview Studio','preview','◉','Front/back production preview'],['Templates','templates','▦','Ready-to-use design presets'],
  ['File Convert','fileconvert','⇄','Convert PNG, JPG, WEBP and SVG'],['Bulk Production','bulk','▱','Generate personalized batches'],['Recent Designs','projects','▣','Manage saved designs'],['Team / Clubs','teams','♙','Manage players and teams'],['Production Sheet','production','▤','Validate and prepare production'],['Order / Export History','orders','↻','Track submissions and exports'],['Brand Assets','brandassets','◇','Logos and reusable assets']
];
function menuDrawer(){return `<div class="drawer-backdrop ${state.menu?'open':''}" onclick="if(event.target===this)toggleMenu()"><aside class="drawer"><div class="drawer-head"><div><h2>Menu</h2><div style="color:var(--muted)">Everything you need for jersey design & production</div></div><button class="iconbtn" onclick="toggleMenu()">✕</button></div>${state.user?`<div class="workspace-card"><b>${esc(state.user.name||'Designer')}</b><small>${esc(state.user.role||'Designer')} · ${esc(state.user.plan||'Workspace')}</small></div>`:''}<div class="menu-group"><label>Workspace & Tools</label>${menuItems.slice(0,5).map(([n,r,i,d])=>`<div class="menuitem" onclick="goto('${r}');toggleMenu()"><span>${i}</span><div><b>${n}</b><small>${d}</small></div><i>›</i></div>`).join('')}</div><div class="menu-group"><label>Production & Management</label><div class="menu-grid">${menuItems.slice(5).map(([n,r,i,d])=>`<div class="menuitem" onclick="goto('${r}');toggleMenu()"><span>${i}</span><div><b>${n}</b><small>${d}</small></div></div>`).join('')}</div></div><div class="menu-group"><label>Account & Support</label><div class="menu-grid"><div class="menuitem" onclick="goto('settings');toggleMenu()"><b>Settings</b></div><div class="menuitem" onclick="goto('help');toggleMenu()"><b>Help & Support</b></div>${state.user?.role==='Studio Owner'?`<div class="menuitem" onclick="goto('admin');toggleMenu()"><b>Admin Panel</b></div>`:''}</div>${state.user?`<div class="menuitem danger-row" onclick="logout()"><b>Logout</b><i>↗</i></div>`:''}</div></aside></div>`;}

function landing(){return `<div class="shell">${topbar('Home')}<main class="container"><section class="hero"><div><div class="eyebrow">From image to reality</div><h1>My Jersey <span>Studio</span></h1><h2>AI-Powered Jersey Design & Production Workflow</h2><p>Turn rough jersey photos and artwork into reusable vectors, customize team designs, personalize entire rosters and deliver factory-ready files from one workspace.</p><div class="hero-cta"><button class="btn primary large" onclick="goto('register')">Start Designing Now →</button><button class="btn large" onclick="document.getElementById('flow').scrollIntoView()">▶ See Workflow</button></div></div><div class="hero-art">${jerseySVG({id:'hero'})}<div class="floating-note">TURN<br>IDEAS<br>INTO<br>JERSEYS ↗</div></div></section><section id="flow" class="features-row">${[['1','Image to Vector','Upload artwork or a jersey image. Cleanup removes simple backgrounds and creates scalable SVG output.'],['2','Customize','Change colors, pattern, logo, player name and number with live front/back editing.'],['3','Bulk Production','Import CSV roster data and generate hundreds of personalized jersey files.'],['4','Production Delivery','Validate assets, make production sheets and export an organized factory ZIP.']].map(([n,t,p])=>`<article class="glass-card feature-card"><div class="step">${n}</div><h3>${t}</h3><p>${p}</p><div class="mini-flow"><div class="mini-box">${n==='1'?'Upload':n==='2'?'Edit':n==='3'?'CSV/XLSX':'Factory'}</div><span>→</span><div class="mini-box">Ready</div></div></article>`).join('')}</section><div class="stats"><div class="glass-card stat"><b>⚡</b><div><strong>Fast</strong><span>Automated workflow</span></div></div><div class="glass-card stat"><b>◇</b><div><strong>Vector</strong><span>SVG master output</span></div></div><div class="glass-card stat"><b>▱</b><div><strong>Bulk</strong><span>Roster personalization</span></div></div><div class="glass-card stat"><b>✓</b><div><strong>Production</strong><span>Validation + packaging</span></div></div></div></main>${menuDrawer()}</div>`;}

function authShell(kind='login'){
  const register=kind==='register';
  return `<div class="shell auth-page"><div class="auth-copy">${brand()}<h1>Gear Your<br><span>Passion</span></h1><p>Premium custom jersey workflow for studios, designers, production managers and factories.</p><div class="auth-benefits"><span>✓ Vector workflow</span><span>✓ Bulk personalization</span><span>✓ Production exports</span></div></div><div class="glass-card auth-card">${brand()}<h2>${register?'Create Workspace':'Welcome Back'}</h2><p>${register?'Create your My Jersey Studio account':'Login to continue to My Jersey Studio'}</p><form class="auth-form" onsubmit="${register?'registerUser(event)':'loginUser(event)'}">${register?`<input id="name" placeholder="Full Name / Studio Name" required>`:''}<input id="email" type="email" placeholder="Email" required><input id="password" type="password" placeholder="Password" required minlength="6"><select id="role"><option>Studio Owner</option><option>Designer</option><option>Production Manager</option><option>Factory / Client</option></select><button class="btn primary large">${register?'Create Account':'Login'} →</button>${!register?`<div class="divider">OR</div><button type="button" class="btn large" onclick="guestLogin()">♙ Continue as Guest</button>`:''}<button type="button" class="ghost-link auth-switch" onclick="goto('${register?'login':'register'}')">${register?'Already have an account? Sign in':'Don’t have an account? Create Account'}</button></form><div class="footer-note">Developed By The Artist · Copyright @2026–2028</div></div></div>`;
}
function login(){return authShell('login');} function registerPage(){return authShell('register');}
async function api(path, options={}){ const headers={...(options.headers||{}),'content-type':'application/json'}; if(state.token) headers.authorization=`Bearer ${state.token}`; const res=await fetch(path,{...options,headers}); let data={}; try{data=await res.json();}catch{} return {ok:res.ok,status:res.status,data}; }
window.loginUser=async e=>{e.preventDefault();const email=document.getElementById('email').value.trim(),password=document.getElementById('password').value,role=document.getElementById('role').value;try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});if(r.ok){state.user=r.data.user;state.token=r.data.token;LS.set('mjs_user',state.user);localStorage.setItem('mjs_token',state.token);goto('dashboard');return;}if(r.status!==503){notify(r.data.message||'Login failed');return;}}catch{}state.user={name:email.split('@')[0]||'Designer',email,role,plan:'Local Workspace'};LS.set('mjs_user',state.user);notify('Backend not configured — using secure local workspace mode');goto('dashboard');};
window.registerUser=async e=>{e.preventDefault();const name=document.getElementById('name').value.trim(),email=document.getElementById('email').value.trim(),password=document.getElementById('password').value,role=document.getElementById('role').value;try{const r=await api('/api/auth/register',{method:'POST',body:JSON.stringify({name,email,password,role})});if(r.ok){state.user=r.data.user;state.token=r.data.token;LS.set('mjs_user',state.user);localStorage.setItem('mjs_token',state.token);goto('dashboard');return;}if(r.status!==503){notify(r.data.message||'Registration failed');return;}}catch{}state.user={name,email,role,plan:'Local Workspace'};LS.set('mjs_user',state.user);notify('Created local workspace account');goto('dashboard');};
window.guestLogin=()=>{state.user={name:'Guest Designer',email:'guest@local',role:'Designer',plan:'Guest'};LS.set('mjs_user',state.user);goto('dashboard');};
window.logout=()=>{LS.del('mjs_user');localStorage.removeItem('mjs_token');state.user=null;state.token='';state.menu=false;goto('landing');};

function requireUser(){return !!state.user;}
function miniJersey(name,accent='#9cff45',num='10',color='#111c1a',pattern='slashes'){return `<div class="project-thumb">${jerseySVG({id:'m'+Math.random().toString(36).slice(2),compact:true,accent,number:num,color,pattern})}<strong>${esc(name)}</strong><small>Saved project</small></div>`;}
function dashboard(){if(!requireUser())return login();const p=state.projects.length,b=state.bulkRows.length,o=state.orders.length,t=state.team.length;return `<div class="shell">${topbar('Home')}<main class="container"><section class="hero dashboard-hero"><div><div class="eyebrow">Welcome back · ${esc(state.user.role||'Designer')}</div><h1>My Jersey <span>Studio</span></h1><p>Design, personalize and manage jerseys from concept to production.</p></div><div class="hero-art">${jerseySVG({id:'dash'})}</div></section><div class="dashboard-grid">${[['Image To Vector','Upload and convert artwork to a clean SVG master.','vector','◈'],['Customize Design','Create a jersey with colors, patterns, logo and player data.','customize','✦'],['Bulk Production','Import roster data and create personalized files.','bulk','▱'],['Production Center','Validate, export and package factory files.','production','✓']].map(([n,d,r,i])=>`<article class="glass-card dash-card"><span class="module-icon">${i}</span><h3>${n}</h3><p>${d}</p><button class="circle-go" onclick="goto('${r}')">→</button></article>`).join('')}</div><div class="stats"><div class="glass-card stat"><b>👕</b><div><strong>${p}</strong><span>Total Designs</span></div></div><div class="glass-card stat"><b>♙</b><div><strong>${t}</strong><span>Team Members</span></div></div><div class="glass-card stat"><b>▱</b><div><strong>${b}</strong><span>Bulk Rows Loaded</span></div></div><div class="glass-card stat"><b>↻</b><div><strong>${o}</strong><span>Orders / Exports</span></div></div></div><section class="section-grid"><div class="glass-card panel"><div class="panel-head"><h3>Recent Projects</h3><button class="ghost-link" onclick="goto('projects')">View All →</button></div><div class="recent-strip">${(state.projects.slice(0,6).length?state.projects.slice(0,6):[{name:'Thunder FC',accent:'#9cff45',number:'10'},{name:'Eagles Club',accent:'#3da6ff',number:'23'},{name:'Dragons',accent:'#ff4a59',number:'10'},{name:'Kings United',accent:'#a657ff',number:'7'},{name:'Valor FC',accent:'#df9c39',number:'10'},{name:'Storm Club',accent:'#b8e8ff',number:'9'}]).map(x=>miniJersey(x.name||x.playerName||'Design',x.accent||'#9cff45',x.number||'10',x.color||'#111c1a',x.pattern||'slashes')).join('')}</div></div><div class="glass-card panel"><div class="panel-head"><h3>Quick Actions</h3></div><div class="quick-grid">${[['New Design','customize'],['Upload Image','vector'],['Production Sheet','production'],['Invite Team','teams']].map(([n,r])=>`<button class="quick-action" onclick="goto('${r}')">${n}<small>Open module →</small></button>`).join('')}</div></div></section></main>${menuDrawer()}</div>`;}

function vectorPage(){if(!requireUser())return login();const src=state.sourceImage,proc=state.processedImage;return `<div class="shell">${topbar('Production')}<main class="container"><div class="workspace-title"><div><div class="eyebrow">Home › Design Tools › Image To Vector</div><h1 class="page-title">Image To <span>Vector</span></h1><p>Convert artwork into a transparent, simplified SVG approximation and carry it directly into the jersey editor.</p></div><div class="pill"><i class="dot"></i> Browser processing · no API required</div></div><section class="workflow"><article class="glass-card workstep"><div class="stephead"><span class="step">1</span><h3>Upload Image</h3></div><div id="dropzone" class="dropzone"><div class="cloud">☁</div><b>Drag & drop your image here</b><small>PNG, JPG, JPEG, WEBP, SVG</small><label class="btn primary file-label">Upload Image<input type="file" hidden accept="image/*,.svg" onchange="loadSource(event)"></label></div><div class="thumb-stage">${src?`<img src="${src}" alt="Uploaded image">`:'<div class="placeholder-art">Your source image appears here.</div>'}</div><div class="controls"><div class="field"><label>Background tolerance <span id="thrVal">${state.cleanupThreshold}</span></label><input class="range" type="range" min="15" max="120" value="${state.cleanupThreshold}" oninput="setThreshold(this.value)"></div><div class="field"><label>Color simplification <span id="stepVal">${state.colorStep}</span></label><input class="range" type="range" min="8" max="64" step="4" value="${state.colorStep}" oninput="setColorStep(this.value)"></div></div></article><article class="glass-card workstep"><div class="stephead"><span class="step">2</span><h3>Vector Cleanup</h3></div><div class="thumb-stage">${proc?`<img src="${proc}" alt="Processed artwork">`:'<div class="placeholder-art">Run cleanup to remove a flat background and simplify colors.</div>'}</div><button class="btn primary" style="margin-top:12px" onclick="processImage()">✦ Run Cleanup</button><div class="checklist"><span>Background estimation</span><span>Transparent output</span><span>Color quantization</span><span>SVG vector approximation</span></div></article><article class="glass-card workstep"><div class="stephead"><span class="step">3</span><h3>Add to Jersey</h3></div><div class="thumb-stage vector-preview">${proc?`<img src="${proc}">`:'<div class="placeholder-art">Processed artwork can become the team logo.</div>'}</div><button class="btn primary" onclick="useAsLogo()">Use as Jersey Logo →</button><div class="field" style="margin-top:15px"><label>AI design instruction</label><textarea id="aiPrompt" placeholder="Make it neon green, simplify the logo, add a stronger outline..."></textarea></div><button class="btn" onclick="aiCommand()">Send to AI Assistant</button></article><article class="glass-card workstep"><div class="stephead"><span class="step">4</span><h3>Preview</h3></div><div class="viewtabs"><button class="active">Front</button><button onclick="goto('preview')">Back</button></div><div class="thumb-stage jersey-preview">${jerseySVG({id:'vprev'})}</div><button class="btn" onclick="goto('customize')">Open Design Studio →</button></article><article class="glass-card workstep"><div class="stephead"><span class="step">5</span><h3>Download</h3></div><div class="download-grid"><div class="filetype"><b>SVG</b><small>Vector master</small></div><div class="filetype"><b>PNG</b><small>Transparent</small></div></div><button class="btn" onclick="downloadVector()">Download SVG</button><button class="btn" onclick="downloadProcessedPNG()">Download PNG</button><button class="btn primary" onclick="goto('customize')">Continue Editing →</button>${state.vectorSVG?'<div class="success-chip">✓ Vector output ready</div>':''}</article></section></main>${menuDrawer()}</div>`;}
window.setThreshold=v=>{state.cleanupThreshold=+v;localStorage.setItem('mjs_threshold',v);document.getElementById('thrVal')&&(document.getElementById('thrVal').textContent=v);};
window.setColorStep=v=>{state.colorStep=+v;localStorage.setItem('mjs_colorstep',v);document.getElementById('stepVal')&&(document.getElementById('stepVal').textContent=v);};
window.loadSource=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.sourceImage=r.result;localStorage.setItem('mjs_source',state.sourceImage);render();notify('Image uploaded');};r.readAsDataURL(f);};
function setupDrop(){const dz=document.getElementById('dropzone');if(!dz)return;['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('drag')}));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('drag')}));dz.addEventListener('drop',e=>{const f=e.dataTransfer.files?.[0];if(f)window.loadSource({target:{files:[f]}});});}
window.processImage=async()=>{if(!state.sourceImage)return notify('Upload an image first');notify('Processing image…');const img=new Image();img.onload=()=>{const max=220,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,w,h);const image=ctx.getImageData(0,0,w,h),d=image.data;const pts=[[0,0],[w-1,0],[0,h-1],[w-1,h-1],[Math.floor(w/2),0],[Math.floor(w/2),h-1]].map(([x,y])=>{const i=(y*w+x)*4;return[d[i],d[i+1],d[i+2]]});const bg=pts.reduce((a,p)=>a.map((v,i)=>v+p[i]),[0,0,0]).map(v=>v/pts.length),step=state.colorStep;for(let i=0;i<d.length;i+=4){const dist=Math.hypot(d[i]-bg[0],d[i+1]-bg[1],d[i+2]-bg[2]);if(dist<state.cleanupThreshold){d[i+3]=0;continue;}d[i]=Math.min(255,Math.round(d[i]/step)*step);d[i+1]=Math.min(255,Math.round(d[i+1]/step)*step);d[i+2]=Math.min(255,Math.round(d[i+2]/step)*step);}ctx.putImageData(image,0,0);state.processedImage=c.toDataURL('image/png');state.vectorSVG=buildVectorSVG(image,w,h);localStorage.setItem('mjs_processed',state.processedImage);localStorage.setItem('mjs_vector',state.vectorSVG);render();notify('Vector cleanup complete');};img.src=state.sourceImage;};
function buildVectorSVG(image,w,h){const d=image.data,rects=[];for(let y=0;y<h;y++){let x=0;while(x<w){let i=(y*w+x)*4;if(d[i+3]<30){x++;continue;}const r=d[i],g=d[i+1],b=d[i+2],a=d[i+3];let run=1;while(x+run<w){const j=(y*w+x+run)*4;if(d[j+3]<30||d[j]!==r||d[j+1]!==g||d[j+2]!==b||d[j+3]!==a)break;run++;}rects.push(`<rect x="${x}" y="${y}" width="${run}" height="1" fill="rgb(${r},${g},${b})" fill-opacity="${(a/255).toFixed(2)}"/>`);x+=run;}}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" shape-rendering="crispEdges">${rects.join('')}</svg>`;}
window.useAsLogo=()=>{if(!state.processedImage)return notify('Run cleanup first');state.logoData=state.processedImage;saveDesignState();notify('Artwork added to jersey');goto('customize');};
window.aiCommand=async()=>{const prompt=document.getElementById('aiPrompt')?.value.trim();if(!prompt)return notify('Write a command first');try{const r=await api('/api/ai',{method:'POST',body:JSON.stringify({prompt,design:designSnapshot()})});if(r.ok){if(r.data.patch)applySnapshot(r.data.patch);notify(r.data.message||'AI instruction applied');render();return;}}catch{}applyLocalAI(prompt);};
function dl(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);}
window.downloadVector=()=>{if(!state.vectorSVG)return notify('Run cleanup first');dl('artwork-vector.svg',new Blob([state.vectorSVG],{type:'image/svg+xml'}));};
window.downloadProcessedPNG=()=>{if(!state.processedImage)return notify('Run cleanup first');const a=document.createElement('a');a.href=state.processedImage;a.download='artwork-clean.png';a.click();};

function customize(){if(!requireUser())return login();return `<div class="shell">${topbar('Design')}<main class="container"><div class="workspace-title"><div><div class="eyebrow">Home › Design › Customize Design Studio</div><h1 class="page-title">Customize <span>Design Studio</span></h1><p>Edit every production detail with live front/back previews.</p></div><button class="btn primary" onclick="saveProject()">Save Project</button></div><section class="editor"><aside class="glass-card tools-panel">${['Jersey Type','Collar','Sleeve','Colors','Patterns','Text','Name & Number','Logos','Badges','Effects','Layers','Background'].map((x,i)=>`<div class="toolitem ${[3,4,6,7].includes(i)?'active':''}"><span>${['👕','⌄','◒','◉','▧','T','⑩','◇','⬡','✦','▱','▨'][i]}</span>${x}<span style="margin-left:auto">›</span></div>`).join('')}</aside><section class="glass-card canvas-wrap"><div class="canvas-top"><div class="viewtabs" style="margin:0"><button class="active">Front + Back</button></div><span class="pill">Live Preview</span></div><div class="studio-stage"><div class="jersey-live">${jerseySVG({id:'edit-front'})}</div><div class="jersey-live">${jerseySVG({id:'edit-back',front:false})}</div></div><div class="glass-card assistant-box"><b style="color:var(--lime)">AI Design Assistant</b><div class="assistant-row"><input id="editAi" placeholder="Make the jersey black and purple, use chevrons, number 23..."><button class="btn primary" onclick="editorAi()">→</button></div></div></section><aside class="glass-card props-panel"><div class="panel-head"><h3>Design Properties</h3><button class="ghost-link" onclick="resetDesign()">Reset</button></div><div class="field"><label>Jersey base color</label><input type="color" value="${state.jerseyColor}" onchange="setColor(this.value)"></div><div class="field"><label>Accent color</label><input type="color" value="${state.accentColor}" onchange="setAccent(this.value)"></div><div class="field"><label>Pattern</label><select onchange="setPattern(this.value)"><option value="slashes" ${state.pattern==='slashes'?'selected':''}>Slashes</option><option value="chevrons" ${state.pattern==='chevrons'?'selected':''}>Chevrons</option><option value="waves" ${state.pattern==='waves'?'selected':''}>Waves</option><option value="none" ${state.pattern==='none'?'selected':''}>None</option></select></div><div class="field"><label>Player name</label><input value="${esc(state.playerName)}" maxlength="18" oninput="setPlayerName(this.value)"></div><div class="field"><label>Number</label><input value="${esc(state.playerNumber)}" maxlength="3" oninput="setPlayerNumber(this.value)"></div><div class="field"><label>Upload team logo</label><input type="file" accept="image/*" onchange="loadLogo(event)"></div><div class="swatches">${[['#9cff45','#111c1a'],['#42a5ff','#0b1322'],['#ff4b5d','#1a090c'],['#a75cff','#120a1d'],['#f1a83c','#181107']].map(([a,c])=>`<button class="swatch" style="background:${a}" onclick="applyPalette('${c}','${a}')" title="Apply palette"></button>`).join('')}</div><div class="panel-head"><h3 style="font-size:14px">Layers</h3></div>${['Team Logo','Number '+esc(state.playerNumber),'Player Name',state.pattern+' Pattern','Main Jersey'].map((x,i)=>`<div class="layer"><span>◉</span><b>${x}</b><span>${i?'Below':'Top'}</span></div>`).join('')}<button class="btn primary" style="width:100%;margin-top:16px" onclick="goto('preview')">Continue to Preview →</button></aside></section></main>${menuDrawer()}</div>`;}
window.setColor=v=>{state.jerseyColor=v;saveDesignState();render();};window.setAccent=v=>{state.accentColor=v;saveDesignState();render();};window.setPattern=v=>{state.pattern=v;saveDesignState();render();};window.setPlayerName=v=>{state.playerName=v.toUpperCase();saveDesignState();render();};window.setPlayerNumber=v=>{state.playerNumber=v.replace(/\D/g,'').slice(0,3)||'0';saveDesignState();render();};window.applyPalette=(c,a)=>{state.jerseyColor=c;state.accentColor=a;saveDesignState();render();};
window.loadLogo=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.logoData=r.result;saveDesignState();render();notify('Logo updated');};r.readAsDataURL(f);};
window.resetDesign=()=>{state.jerseyColor='#111c1a';state.accentColor='#9cff45';state.playerName='YOUR NAME';state.playerNumber='10';state.logoData='';state.pattern='slashes';saveDesignState();render();notify('Design reset');};
function applyLocalAI(prompt){const p=prompt.toLowerCase(),colors={blue:'#37a8ff',red:'#ff4859',purple:'#ae65ff',green:'#9cff45',neon:'#9cff45',orange:'#ff9c3d',pink:'#ff5aac',gold:'#e6b64d',cyan:'#30e3d4'};for(const [word,c] of Object.entries(colors))if(p.includes(word))state.accentColor=c;if(p.includes('black'))state.jerseyColor='#080d0c';if(p.includes('white'))state.jerseyColor='#f3f5f3';if(p.includes('chevron'))state.pattern='chevrons';if(p.includes('wave'))state.pattern='waves';if(p.includes('no pattern')||p.includes('plain'))state.pattern='none';const num=p.match(/(?:number|no\.?)[^0-9]*(\d{1,3})/);if(num)state.playerNumber=num[1];saveDesignState();render();notify('Applied locally understood design command');}
window.editorAi=async()=>{const prompt=document.getElementById('editAi')?.value.trim();if(!prompt)return notify('Write an instruction');try{const r=await api('/api/ai',{method:'POST',body:JSON.stringify({prompt,design:designSnapshot()})});if(r.ok&&r.data.patch){applySnapshot(r.data.patch);render();notify(r.data.message||'AI design patch applied');return;}}catch{}applyLocalAI(prompt);};
window.saveProject=async()=>{const name=state.playerName==='YOUR NAME'?`Jersey ${new Date().toLocaleDateString()}`:`${state.playerName} ${state.playerNumber}`;const project={id:Date.now(),name,...designSnapshot(),created:new Date().toISOString(),updated:new Date().toISOString()};state.projects.unshift(project);state.projects=state.projects.slice(0,100);LS.set('mjs_projects',state.projects);notify('Project saved');try{await api('/api/projects',{method:'POST',body:JSON.stringify(project)});}catch{};};

function preview(){if(!requireUser())return login();return `<div class="shell">${topbar('Design')}<main class="container"><div class="workspace-title"><div><div class="eyebrow">Production Preview</div><h1 class="page-title">Preview <span>Studio</span></h1><p>Inspect front and back, then export the master artwork.</p></div><div><button class="btn" onclick="goto('customize')">← Edit</button> <button class="btn primary" onclick="exportFactoryZip()">Factory ZIP</button></div></div><section class="section-grid preview-grid"><div class="glass-card panel preview-card"><div class="panel-head"><h3>Front View</h3><span class="pill">Production preview</span></div><div class="big-jersey">${jerseySVG({id:'prev-front'})}</div></div><div class="glass-card panel preview-card"><div class="panel-head"><h3>Back View</h3><span class="pill">Name + number</span></div><div class="big-jersey">${jerseySVG({id:'prev-back',front:false})}</div></div></section><div class="glass-card panel" style="margin-top:16px"><div class="panel-head"><h3>Export</h3><span class="muted-note">SVG is native vector for the jersey template. Raster logos remain embedded unless vectorized first.</span></div><div class="export-actions"><button class="btn" onclick="exportJerseySVG()">SVG Front</button><button class="btn" onclick="exportJerseySVG(true)">SVG Back</button><button class="btn" onclick="exportJerseyPNG(false)">PNG Front</button><button class="btn" onclick="exportJerseyPNG(true)">PNG Back</button><button class="btn primary" onclick="saveProject()">Save Project</button></div></div></main>${menuDrawer()}</div>`;}
function cleanSvg(svg){return svg.replace(/class="jersey-svg[^\"]*"/,'');}
window.exportJerseySVG=(back=false)=>{const svg=cleanSvg(jerseySVG({id:'export'+Date.now(),front:!back}));dl(`jersey-${back?'back':'front'}.svg`,new Blob([svg],{type:'image/svg+xml'}));};
function svgToPngBlob(svg,w=1200,h=1440){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(url);b?resolve(b):reject(new Error('png'));},'image/png');};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('svg'));};img.src=url;});}
window.exportJerseyPNG=async(back=false)=>{const svg=cleanSvg(jerseySVG({id:'png'+Date.now(),front:!back}));dl(`jersey-${back?'back':'front'}.png`,await svgToPngBlob(svg));};

const presets=[
  {name:'Neon Tiger',color:'#0b1512',accent:'#9cff45',pattern:'slashes'},{name:'Blue Lightning',color:'#071527',accent:'#37a8ff',pattern:'chevrons'},{name:'Red Fury',color:'#18090d',accent:'#ff4859',pattern:'slashes'},{name:'Purple Strike',color:'#140b1d',accent:'#ae65ff',pattern:'chevrons'},{name:'Gold Elite',color:'#171006',accent:'#e6b64d',pattern:'waves'},{name:'White Phantom',color:'#e9efec',accent:'#a8c7d4',pattern:'none'},{name:'Orange Blaze',color:'#171008',accent:'#ff9838',pattern:'waves'},{name:'Pink Thunder',color:'#170b15',accent:'#ff5aac',pattern:'slashes'}
];
function templates(){if(!requireUser())return login();return modulePage('Templates','Design','Start with a production-ready color and pattern preset.',`<div class="template-grid">${presets.map((p,i)=>`<article class="glass-card template-card"><div class="template-jersey">${jerseySVG({id:'tpl'+i,color:p.color,accent:p.accent,pattern:p.pattern,number:String(10+i)})}</div><h3>${p.name}</h3><small>${p.pattern} pattern</small><button class="btn primary" onclick="applyTemplate(${i})">Use Template</button></article>`).join('')}</div>`);}
window.applyTemplate=i=>{const p=presets[i];state.jerseyColor=p.color;state.accentColor=p.accent;state.pattern=p.pattern;saveDesignState();goto('customize');notify(`${p.name} applied`);};

function projects(){if(!requireUser())return login();const rows=state.projects.length?state.projects.map((p,i)=>`<article class="glass-card project-card"><div class="project-card-preview">${jerseySVG({id:'proj'+i,color:p.color,accent:p.accent,name:p.name,number:p.number,logo:p.logo,pattern:p.pattern})}</div><div class="project-meta"><h3>${esc(p.name)}</h3><small>${new Date(p.created).toLocaleString()}</small><div class="project-actions"><button class="btn primary" onclick="openProject(${i})">Open</button><button class="btn" onclick="exportProject(${i})">Export SVG</button><button class="btn danger" onclick="deleteProject(${i})">Delete</button></div></div></article>`).join(''):`<div class="glass-card empty-state"><h3>No saved designs yet</h3><p>Create a jersey and click Save Project.</p><button class="btn primary" onclick="goto('customize')">Create Design</button></div>`;return modulePage('My Projects','My Projects','Saved jersey designs, production masters and recent work.',`<div class="project-list">${rows}</div>`);}
window.openProject=i=>{const p=state.projects[i];if(!p)return;applySnapshot(p);goto('customize');};
window.deleteProject=i=>{state.projects.splice(i,1);LS.set('mjs_projects',state.projects);render();notify('Project deleted');};
window.exportProject=i=>{const p=state.projects[i];if(!p)return;const svg=cleanSvg(jerseySVG({id:'saved'+Date.now(),color:p.color,accent:p.accent,name:p.name,number:p.number,logo:p.logo,pattern:p.pattern}));dl(`${slug(p.name)}.svg`,new Blob([svg],{type:'image/svg+xml'}));};

function fileConvert(){if(!requireUser())return login();return modulePage('File Convert','Production','Convert uploaded artwork into common production formats.',`<section class="section-grid"><div class="glass-card panel"><h3>1. Upload File</h3><label class="dropzone file-label"><div class="cloud">⇄</div><b>Choose image or SVG</b><small>PNG, JPG, WEBP, SVG</small><input type="file" hidden accept="image/*,.svg" onchange="loadConvert(event)"></label><div class="thumb-stage">${state.convertSource?`<img src="${state.convertSource}">`:'<div class="placeholder-art">Preview appears here.</div>'}</div></div><div class="glass-card panel"><h3>2. Convert & Download</h3><p class="muted-note">Raster targets are rendered through browser Canvas. SVG target wraps the current image in a scalable SVG canvas.</p><div class="convert-grid">${['PNG','JPEG','WEBP','SVG'].map(x=>`<button class="format-button" onclick="convertCurrent('${x.toLowerCase()}')"><b>${x}</b><span>Convert file</span></button>`).join('')}</div></div></section>`);}
window.loadConvert=e=>{const f=e.target.files?.[0];if(!f)return;state.convertName=f.name.replace(/\.[^.]+$/,'');const r=new FileReader();r.onload=()=>{state.convertSource=r.result;render();};r.readAsDataURL(f);};
window.convertCurrent=async type=>{if(!state.convertSource)return notify('Upload a file first');if(type==='svg'){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1600" viewBox="0 0 1600 1600"><image href="${state.convertSource}" width="1600" height="1600" preserveAspectRatio="xMidYMid meet"/></svg>`;dl(`${state.convertName||'converted'}.svg`,new Blob([svg],{type:'image/svg+xml'}));return;}const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),max=2400,scale=Math.min(1,max/Math.max(img.width,img.height));c.width=Math.round(img.width*scale)||1200;c.height=Math.round(img.height*scale)||1200;c.getContext('2d').drawImage(img,0,0,c.width,c.height);const mime=type==='jpeg'?'image/jpeg':type==='webp'?'image/webp':'image/png';c.toBlob(b=>dl(`${state.convertName||'converted'}.${type==='jpeg'?'jpg':type}`,b),mime,type==='jpeg'?0.95:0.92);};img.src=state.convertSource;};

function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&q&&n==='"'){cell+='"';i++;}else if(c==='"')q=!q;else if(c===','&&!q){row.push(cell.trim());cell='';}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(cell.trim());cell='';if(row.some(Boolean))rows.push(row);row=[];}else cell+=c;}row.push(cell.trim());if(row.some(Boolean))rows.push(row);if(!rows.length)return[];const head=rows.shift().map(x=>x.toLowerCase().replace(/\s+/g,'_'));return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]??''])));}
function normalizeBulk(rows){return rows.map((r,i)=>({name:(r.name||r.player||r.player_name||`PLAYER ${i+1}`).toUpperCase(),number:String(r.number||r.no||r.jersey_number||i+1),size:(r.size||'M').toUpperCase(),qty:+(r.qty||r.quantity||1)||1,team:r.team||r.club||'Team'}));}
function bulk(){if(!requireUser())return login();return modulePage('Bulk Production','Production','Import roster data and generate personalized front/back SVG files for every player.',`<div class="bulk-layout"><div class="glass-card panel"><h3>Roster Input</h3><p class="muted-note">Required headers: name, number. Optional: size, qty, team.</p><textarea id="csvInput" class="csv-area" placeholder="name,number,size,qty,team\nRafi,10,M,1,Tigers\nNahid,7,L,2,Tigers"></textarea><div class="button-row"><button class="btn" onclick="loadSampleCSV()">Load Sample</button><label class="btn file-label">Upload CSV<input type="file" hidden accept=".csv,text/csv" onchange="uploadCSV(event)"></label><button class="btn primary" onclick="parseBulkFromBox()">Parse Roster</button></div></div><div class="glass-card panel"><div class="panel-head"><h3>Batch Summary</h3><span class="pill">${state.bulkRows.length} players</span></div><div class="summary-numbers"><div><b>${state.bulkRows.reduce((a,r)=>a+(+r.qty||1),0)}</b><span>Total jerseys</span></div><div><b>${new Set(state.bulkRows.map(r=>r.size)).size}</b><span>Sizes</span></div><div><b>${new Set(state.bulkRows.map(r=>r.team)).size}</b><span>Teams</span></div></div><button class="btn primary" style="width:100%" onclick="generateBulkZip()">Generate Factory ZIP →</button></div></div><div class="glass-card panel" style="margin-top:16px"><div class="panel-head"><h3>Personalization Queue</h3><button class="ghost-link" onclick="clearBulk()">Clear</button></div>${bulkTable()}</div>`);}
function bulkTable(){if(!state.bulkRows.length)return `<div class="empty-inline">No roster loaded yet.</div>`;return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Name</th><th>Number</th><th>Size</th><th>Qty</th><th>Team</th><th>Preview</th></tr></thead><tbody>${state.bulkRows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td>${esc(r.number)}</td><td>${esc(r.size)}</td><td>${r.qty}</td><td>${esc(r.team)}</td><td><button class="mini-btn" onclick="previewBulk(${i})">Open</button></td></tr>`).join('')}</tbody></table></div>`;}
window.loadSampleCSV=()=>{document.getElementById('csvInput').value='name,number,size,qty,team\nRAFI,10,M,1,TIGERS\nNAHID,7,L,2,TIGERS\nMUNIRA,23,S,1,TIGERS\nRAIHAN,11,XL,1,TIGERS';};
window.uploadCSV=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.bulkRows=normalizeBulk(parseCSV(r.result));LS.set('mjs_bulk',state.bulkRows);render();notify(`${state.bulkRows.length} players loaded`);};r.readAsText(f);};
window.parseBulkFromBox=()=>{state.bulkRows=normalizeBulk(parseCSV(document.getElementById('csvInput').value));LS.set('mjs_bulk',state.bulkRows);render();notify(`${state.bulkRows.length} players parsed`);};
window.clearBulk=()=>{state.bulkRows=[];LS.set('mjs_bulk',[]);render();};
window.previewBulk=i=>{const r=state.bulkRows[i];if(!r)return;state.playerName=r.name;state.playerNumber=r.number;saveDesignState();goto('preview');};

function teams(){if(!requireUser())return login();return modulePage('Team / Clubs','Production','Maintain a reusable roster for design and production.',`<section class="section-grid"><div class="glass-card panel"><h3>Add Team Member</h3><form class="stack-form" onsubmit="addTeamMember(event)"><input id="tmName" placeholder="Player name" required><input id="tmNumber" placeholder="Jersey number" required><select id="tmSize"><option>S</option><option selected>M</option><option>L</option><option>XL</option><option>2XL</option></select><input id="tmClub" placeholder="Club / Team" value="My Club"><button class="btn primary">Add Member</button></form></div><div class="glass-card panel"><h3>Team Stats</h3><div class="summary-numbers"><div><b>${state.team.length}</b><span>Members</span></div><div><b>${new Set(state.team.map(x=>x.club)).size}</b><span>Clubs</span></div><div><b>${new Set(state.team.map(x=>x.size)).size}</b><span>Sizes</span></div></div><button class="btn" onclick="teamToBulk()">Send Team to Bulk Production</button></div></section><div class="glass-card panel" style="margin-top:16px"><div class="panel-head"><h3>Roster</h3><button class="ghost-link" onclick="clearTeam()">Clear</button></div>${state.team.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>No.</th><th>Size</th><th>Club</th><th></th></tr></thead><tbody>${state.team.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${esc(x.number)}</td><td>${esc(x.size)}</td><td>${esc(x.club)}</td><td><button class="mini-btn" onclick="removeTeam(${i})">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-inline">No team members yet.</div>'}</div>`);}
window.addTeamMember=e=>{e.preventDefault();state.team.push({name:document.getElementById('tmName').value.toUpperCase(),number:document.getElementById('tmNumber').value,size:document.getElementById('tmSize').value,club:document.getElementById('tmClub').value||'My Club',qty:1});LS.set('mjs_team',state.team);render();};window.removeTeam=i=>{state.team.splice(i,1);LS.set('mjs_team',state.team);render();};window.clearTeam=()=>{state.team=[];LS.set('mjs_team',[]);render();};window.teamToBulk=()=>{state.bulkRows=state.team.map(x=>({...x,team:x.club}));LS.set('mjs_bulk',state.bulkRows);goto('bulk');};

function brandAssets(){if(!requireUser())return login();return modulePage('Brand Assets','Production','Save reusable team logos, sponsor marks and badges.',`<div class="glass-card panel"><div class="panel-head"><h3>Asset Library</h3><label class="btn primary file-label">Upload Asset<input type="file" hidden accept="image/*,.svg" onchange="addAsset(event)"></label></div><div class="asset-grid">${state.assets.length?state.assets.map((a,i)=>`<article class="asset-card"><img src="${a.data}" alt="${esc(a.name)}"><b>${esc(a.name)}</b><div><button class="mini-btn" onclick="useAsset(${i})">Use Logo</button><button class="mini-btn" onclick="deleteAsset(${i})">Delete</button></div></article>`).join(''):'<div class="empty-inline">Upload a logo or sponsor asset to reuse it across projects.</div>'}</div></div>`);}
window.addAsset=e=>{const f=e.target.files?.[0];if(!f)return;if(state.assets.length>=10)return notify('Asset limit reached in local mode');const r=new FileReader();r.onload=()=>{state.assets.unshift({name:f.name,data:r.result,created:Date.now()});LS.set('mjs_assets',state.assets);render();};r.readAsDataURL(f);};window.useAsset=i=>{state.logoData=state.assets[i]?.data||'';saveDesignState();goto('customize');};window.deleteAsset=i=>{state.assets.splice(i,1);LS.set('mjs_assets',state.assets);render();};

function production(){if(!requireUser())return login();const checks=[['Front vector generated',true],['Back vector generated',true],['Player name present',!!state.playerName],['Player number present',!!state.playerNumber],['Team logo attached',!!state.logoData],['Bulk roster loaded',state.bulkRows.length>0]];return modulePage('Production Center','Production','Validate the current design and prepare factory-ready deliverables.',`<div class="production-grid"><div class="glass-card panel"><div class="panel-head"><h3>Production Validation</h3><span class="pill">${checks.filter(x=>x[1]).length}/${checks.length} checks</span></div><div class="validation-list">${checks.map(([n,ok])=>`<div class="validation-row ${ok?'ok':'warn'}"><span>${ok?'✓':'!'}</span><b>${n}</b><small>${ok?'Ready':'Optional / needs attention'}</small></div>`).join('')}</div></div><div class="glass-card panel"><h3>Current Specification</h3><dl class="spec-list"><dt>Player</dt><dd>${esc(state.playerName)}</dd><dt>Number</dt><dd>${esc(state.playerNumber)}</dd><dt>Pattern</dt><dd>${esc(state.pattern)}</dd><dt>Base</dt><dd><i class="color-dot" style="background:${state.jerseyColor}"></i>${state.jerseyColor}</dd><dt>Accent</dt><dd><i class="color-dot" style="background:${state.accentColor}"></i>${state.accentColor}</dd><dt>Bulk rows</dt><dd>${state.bulkRows.length}</dd></dl></div><div class="glass-card panel"><h3>Deliverables</h3><div class="stack-buttons"><button class="btn" onclick="exportProductionPDF()">Production Sheet PDF</button><button class="btn" onclick="exportJerseySVG()">Front SVG</button><button class="btn" onclick="exportJerseySVG(true)">Back SVG</button><button class="btn primary" onclick="exportFactoryZip()">Factory ZIP Package</button><button class="btn" onclick="goto('orders')">Submit / Track Order →</button></div></div></div>`);}

function orders(){if(!requireUser())return login();return modulePage('Order / Export History','Production','Package production files and record factory/client submissions.',`<section class="section-grid"><div class="glass-card panel"><h3>Create Order Submission</h3><form class="stack-form" onsubmit="submitOrder(event)"><input id="orderFactory" placeholder="Factory / Client name" required><input id="orderEmail" type="email" placeholder="Production email" required><input id="orderRef" placeholder="Order reference / PO number"><textarea id="orderNotes" placeholder="Production notes, fabric, print instructions..."></textarea><button class="btn primary">Create Submission</button></form></div><div class="glass-card panel"><h3>What gets packaged</h3><div class="checklist"><span>Front master SVG</span><span>Back master SVG</span><span>Production specification PDF</span><span>Bulk personalized files when roster exists</span><span>Manifest / CSV</span></div><button class="btn" onclick="exportFactoryZip()">Download Factory ZIP Now</button></div></section><div class="glass-card panel" style="margin-top:16px"><div class="panel-head"><h3>History</h3><span class="pill">${state.orders.length} records</span></div>${state.orders.length?`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Factory / Client</th><th>Email</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody>${state.orders.map((o,i)=>`<tr><td>${esc(o.ref||String(o.id).slice(-6))}</td><td>${esc(o.factory)}</td><td>${esc(o.email)}</td><td><span class="status-chip">${esc(o.status)}</span></td><td>${new Date(o.created).toLocaleString()}</td><td><button class="mini-btn" onclick="removeOrder(${i})">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-inline">No submissions yet.</div>'}</div>`);}
window.submitOrder=async e=>{e.preventDefault();const order={id:Date.now(),factory:document.getElementById('orderFactory').value,email:document.getElementById('orderEmail').value,ref:document.getElementById('orderRef').value||`MJS-${Date.now().toString().slice(-6)}`,notes:document.getElementById('orderNotes').value,status:'Prepared',created:new Date().toISOString(),design:designSnapshot(),bulkCount:state.bulkRows.length};state.orders.unshift(order);LS.set('mjs_orders',state.orders);try{const r=await api('/api/orders',{method:'POST',body:JSON.stringify(order)});if(r.ok)order.status='Submitted';}catch{}LS.set('mjs_orders',state.orders);notify('Order record created');render();};window.removeOrder=i=>{state.orders.splice(i,1);LS.set('mjs_orders',state.orders);render();};

function admin(){if(!requireUser())return login();if(state.user.role!=='Studio Owner')return modulePage('Admin Panel','Home','This workspace role does not have owner access.',`<div class="glass-card empty-state"><h3>Owner access required</h3><p>Sign in as Studio Owner to use administration tools.</p></div>`);return modulePage('Admin Panel','Home','Local administration overview with backend readiness checks.',`<div class="stats"><div class="glass-card stat"><b>👕</b><div><strong>${state.projects.length}</strong><span>Projects</span></div></div><div class="glass-card stat"><b>♙</b><div><strong>${state.team.length}</strong><span>Players</span></div></div><div class="glass-card stat"><b>↻</b><div><strong>${state.orders.length}</strong><span>Orders</span></div></div><div class="glass-card stat"><b>◇</b><div><strong>${state.assets.length}</strong><span>Brand Assets</span></div></div></div><section class="section-grid"><div class="glass-card panel"><h3>System Status</h3><div id="systemStatus" class="status-box">Click to test Cloudflare Functions / D1 / AI availability.</div><button class="btn primary" onclick="checkBackend()">Run Backend Check</button></div><div class="glass-card panel"><h3>Workspace Controls</h3><div class="stack-buttons"><button class="btn" onclick="exportWorkspace()">Export Workspace JSON</button><button class="btn" onclick="goto('settings')">Open Settings</button><button class="btn danger" onclick="clearDemoData()">Clear Workspace Data</button></div></div></section>`);}
window.checkBackend=async()=>{const box=document.getElementById('systemStatus');box.textContent='Checking…';try{const res=await fetch('/api/health');const d=await res.json();box.innerHTML=`<b>${res.ok?'Backend online':'Backend error'}</b><br>${esc(JSON.stringify(d))}`;}catch{box.textContent='Static/local mode: backend endpoint unavailable.';}};

function settings(){if(!requireUser())return login();return modulePage('Settings','Home','Workspace preferences, backup and restore.',`<section class="section-grid"><div class="glass-card panel"><h3>Preferences</h3><div class="stack-form"><label class="toggle-row">Theme <button class="btn" onclick="toggleTheme()">${state.dark?'Dark':'Light Preview'}</button></label><label class="toggle-row">Language <button class="btn" onclick="toggleLang()">${state.lang}</button></label><label class="toggle-row">Role <span class="pill">${esc(state.user.role||'Designer')}</span></label></div></div><div class="glass-card panel"><h3>Backup & Restore</h3><div class="stack-buttons"><button class="btn primary" onclick="exportWorkspace()">Export Workspace JSON</button><label class="btn file-label">Import Workspace JSON<input type="file" hidden accept="application/json,.json" onchange="importWorkspace(event)"></label><button class="btn danger" onclick="clearDemoData()">Clear Workspace Data</button></div></div></section>`);}
window.exportWorkspace=()=>{const data={version:2,created:new Date().toISOString(),user:state.user,projects:state.projects,orders:state.orders,team:state.team,assets:state.assets,bulkRows:state.bulkRows,design:designSnapshot()};dl('my-jersey-studio-workspace.json',new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));};
window.importWorkspace=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);state.projects=d.projects||[];state.orders=d.orders||[];state.team=d.team||[];state.assets=d.assets||[];state.bulkRows=d.bulkRows||[];applySnapshot(d.design||{});LS.set('mjs_projects',state.projects);LS.set('mjs_orders',state.orders);LS.set('mjs_team',state.team);LS.set('mjs_assets',state.assets);LS.set('mjs_bulk',state.bulkRows);render();notify('Workspace restored');}catch{notify('Invalid workspace JSON');}};r.readAsText(f);};
window.clearDemoData=()=>{if(!confirm('Clear projects, orders, team, assets and bulk data?'))return;state.projects=[];state.orders=[];state.team=[];state.assets=[];state.bulkRows=[];['mjs_projects','mjs_orders','mjs_team','mjs_assets','mjs_bulk'].forEach(k=>LS.set(k,[]));render();notify('Workspace data cleared');};
function help(){if(!requireUser())return login();return modulePage('Help & Support','Home','Quick guide to the production workflow.',`<div class="help-grid">${[['1. Vectorize','Upload a source image in Image To Vector, tune background tolerance, and run cleanup.'],['2. Design','Use Customize Design Studio to set colors, pattern, logo, player name and number.'],['3. Personalize','Import CSV roster data in Bulk Production or reuse the Team / Clubs roster.'],['4. Validate','Open Production Center and confirm the current design specification.'],['5. Deliver','Download the Factory ZIP or create an order record for a factory/client.'],['Cloud Backend','Bind a Cloudflare D1 database as DB and Workers AI as AI to enable server accounts, sync and AI responses.']].map(([h,p])=>`<article class="glass-card help-card"><h3>${h}</h3><p>${p}</p></article>`).join('')}</div>`);}

function modulePage(title,active,desc,content){return `<div class="shell">${topbar(active)}<main class="container"><div class="workspace-title"><div><div class="eyebrow">My Jersey Studio</div><h1 class="page-title">${title.includes(' ')?title.replace(/ ([^ ]+)$/,' <span>$1</span>'):title}</h1><p>${desc}</p></div></div>${content}</main>${menuDrawer()}</div>`;}

function slug(s){return String(s||'jersey').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'jersey';}
function strBytes(s){return new TextEncoder().encode(s);}
function concatBytes(parts){const len=parts.reduce((a,p)=>a+p.length,0),out=new Uint8Array(len);let o=0;for(const p of parts){out.set(p,o);o+=p.length;}return out;}
const crcTable=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
function le16(n){return new Uint8Array([n&255,(n>>>8)&255]);}function le32(n){return new Uint8Array([n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]);}
function createZip(files){const locals=[],centrals=[];let offset=0;for(const f of files){const name=strBytes(f.name),data=f.data instanceof Uint8Array?f.data:strBytes(f.data),crc=crc32(data);const local=concatBytes([le32(0x04034b50),le16(20),le16(0),le16(0),le16(0),le16(0),le32(crc),le32(data.length),le32(data.length),le16(name.length),le16(0),name,data]);locals.push(local);const central=concatBytes([le32(0x02014b50),le16(20),le16(20),le16(0),le16(0),le16(0),le16(0),le32(crc),le32(data.length),le32(data.length),le16(name.length),le16(0),le16(0),le16(0),le16(0),le32(0),le32(offset),name]);centrals.push(central);offset+=local.length;}const body=concatBytes(locals),cd=concatBytes(centrals),end=concatBytes([le32(0x06054b50),le16(0),le16(0),le16(files.length),le16(files.length),le32(cd.length),le32(body.length),le16(0)]);return new Blob([body,cd,end],{type:'application/zip'});}
function makeProductionText(rows=state.bulkRows){const lines=['MY JERSEY STUDIO - PRODUCTION SHEET','',`Generated: ${new Date().toLocaleString()}`,`Base color: ${state.jerseyColor}`,`Accent color: ${state.accentColor}`,`Pattern: ${state.pattern}`,`Master player: ${state.playerName} #${state.playerNumber}`,'',rows.length?'ROSTER':'SINGLE DESIGN'];if(rows.length){lines.push('Name | Number | Size | Qty | Team');rows.forEach(r=>lines.push(`${r.name} | ${r.number} | ${r.size} | ${r.qty} | ${r.team}`));}return lines.join('\n');}
function simplePDF(text){const lines=text.split('\n').slice(0,55);const escPdf=s=>s.replace(/([\\()])/g,'\\$1');let stream='BT\n/F1 11 Tf\n45 800 Td\n';lines.forEach((l,i)=>{if(i)stream+='0 -14 Td\n';stream+=`(${escPdf(l)}) Tj\n`;});stream+='ET';const objs=[];objs[1]='<< /Type /Catalog /Pages 2 0 R >>';objs[2]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';objs[3]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>';objs[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';objs[5]=`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`;let pdf='%PDF-1.4\n',offs=[0];for(let i=1;i<=5;i++){offs[i]=pdf.length;pdf+=`${i} 0 obj\n${objs[i]}\nendobj\n`;}const x=pdf.length;pdf+='xref\n0 6\n0000000000 65535 f \n';for(let i=1;i<=5;i++)pdf+=String(offs[i]).padStart(10,'0')+' 00000 n \n';pdf+=`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${x}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'});}
window.exportProductionPDF=()=>dl('production-sheet.pdf',simplePDF(makeProductionText()));
async function factoryFiles(rows=state.bulkRows){const files=[];if(rows.length){for(const r of rows){const base=`players/${slug(r.name)}-${r.number}`;files.push({name:`${base}-front.svg`,data:cleanSvg(jerseySVG({id:'bf'+r.number+Math.random(),front:true,name:r.name,number:r.number}))});files.push({name:`${base}-back.svg`,data:cleanSvg(jerseySVG({id:'bb'+r.number+Math.random(),front:false,name:r.name,number:r.number}))});}files.push({name:'roster.csv',data:'name,number,size,qty,team\n'+rows.map(r=>[r.name,r.number,r.size,r.qty,r.team].map(x=>`"${String(x).replace(/"/g,'""')}"`).join(',')).join('\n')});}else{files.push({name:'master/jersey-front.svg',data:cleanSvg(jerseySVG({id:'zf'+Date.now(),front:true}))},{name:'master/jersey-back.svg',data:cleanSvg(jerseySVG({id:'zb'+Date.now(),front:false}))});}files.push({name:'production-sheet.txt',data:makeProductionText(rows)},{name:'manifest.json',data:JSON.stringify({generated:new Date().toISOString(),design:designSnapshot(),players:rows.length,application:'My Jersey Studio v2'},null,2)});return files;}
window.generateBulkZip=async()=>{if(!state.bulkRows.length)return notify('Load a roster first');notify('Building personalized factory package…');dl('bulk-production.zip',createZip(await factoryFiles(state.bulkRows)));notify('Bulk ZIP ready');};
window.exportFactoryZip=async()=>{notify('Packaging production files…');dl('my-jersey-factory-package.zip',createZip(await factoryFiles()));notify('Factory ZIP ready');};

function render(){applyTheme();const map={landing,login,register:registerPage,dashboard,vector:vectorPage,customize,preview,templates,projects,fileconvert:fileConvert,bulk,teams,brandassets:brandAssets,production,orders,admin,settings,help};app.innerHTML=(map[state.route]||landing)();setTimeout(setupDrop,0);}
render();
